Now JS. Start with textures.js.

Canvas texture utilities:
```js
import * as THREE from 'three';
function canvas(w,h){...}
export function makeRoadTexture()
export function makeFacadeTexture(opts)
export function makeSignTexture(text, {bg, fg})
export function makeRickshawArtTexture()
export function makeBannerTexture(text)
export function makeBusTexture(color, text)
export function makeGlowTexture()
export function makeMangoTexture? no
export function makeCloudTexture()
export function makeShopTexture?
```

Road texture: canvas 512x1024 representing 11m x 20m? Repeat along z 30 times over 600 length => 20m per tile. Draw asphalt base #2a2429 with noise speckles, cracks, dashed lane lines at x positions corresponding to lane boundaries. Road width 11: lanes centers -2.6,0,2.6, boundaries at -1.3, 1.3. Edge lines at ±5.2. Dashes along v. Also manhole? Keep clean. Draw dashed lines white/yellow with worn alpha.

Facade: 256x512. Base color palette of Dhaka buildings: dusty pink #b96a5c, teal #3f7f76, ochre #c08a4a, cream #cbb59a, purple #6d5a7a, mint #7fa89a, brick #8d4f42. Draw concrete noise, floors 6-12, windows in grid; some lit warm (#ffc46b), some dark (#1a1f2c) with reflections; balconies rails; grime streaks; rooftop parapet. Emissive map: same canvas but black except windows lit? Create separate emissive canvas with lit windows only. Return {map, emissiveMap}. That doubles textures but okay (~256x512 x 20 = 10MB). Limit variants to 8 and reuse.

Signs: text with Bengali font; font may not be ready when canvas draws (document.fonts.ready). We can await document.fonts.ready before building textures. In main, `await document.fonts.ready` then init. Good.

Rickshaw art: 256x256, dark red background, concentric floral patterns with teal/yellow/pink, peacock-ish arcs, dots. Use for side panels and back.

Banner: 512x128 with text "সাবধান" or "ঈদ মোবারক" on striped background.

Bus texture: 512x256 side with windows, stripes, Bengali text "বাংলা পরিবহন". Material for bus sides.

Cloud texture: radial soft blobs.

Glow texture: radial gradient white->transparent.

Also road pothole texture? Use geometry.

Text rendering Bengali requires font loaded; call after fonts.ready.

Write textures.js.

input.content:
import * as THREE from 'three';

const BENGALI_FONT = '"Hind Siliguri", "Noto Sans Bengali", sans-serif';

function makeCanvas(width, height) {
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  return canvas;
}

function rand(min, max) {
  return min + Math.random() * (max - min);
}

function textureFrom(canvas, { repeatX = 1, repeatY = 1, colorSpace = true } = {}) {
  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;
  texture.repeat.set(repeatX, repeatY);
  texture.anisotropy = 8;
  if (colorSpace) texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}

function noise(ctx, width, height, amount = 2200, alpha = 0.05) {
  for (let i = 0; i < amount; i++) {
    const shade = Math.random() > 0.5 ? 255 : 0;
    ctx.fillStyle = `rgba(${shade},${shade},${shade},${Math.random() * alpha})`;
    ctx.fillRect(Math.random() * width, Math.random() * height, Math.random() * 3 + 1, Math.random() * 3 + 1);
  }
}

export function makeRoadTexture() {
  const w = 512;
  const h = 1024;
  const c = makeCanvas(w, h);
  const ctx = c.getContext('2d');
  const grd = ctx.createLinearGradient(0, 0, w, 0);
  grd.addColorStop(0, '#241f25');
  grd.addColorStop(0.5, '#2e282e');
  grd.addColorStop(1, '#241f25');
  ctx.fillStyle = grd;
  ctx.fillRect(0, 0, w, h);
  noise(ctx, w, h, 9000, 0.07);

  // patchy repairs
  for (let i = 0; i < 9; i++) {
    ctx.fillStyle = `rgba(${rand(20, 40) | 0},${rand(18, 34) | 0},${rand(20, 36) | 0},0.5)`;
    ctx.beginPath();
    ctx.ellipse(rand(0, w), rand(0, h), rand(18, 80), rand(30, 120), rand(0, 6), 0, Math.PI * 2);
    ctx.fill();
  }

  // lane boundaries at 1/3 and 2/3 (three lanes)
  ctx.lineWidth = 5;
  ctx.strokeStyle = 'rgba(255, 238, 198, 0.68)';
  ctx.setLineDash([54, 42]);
  for (const x of [w / 3, (w * 2) / 3]) {
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, h);
    ctx.stroke();
  }
  ctx.setLineDash([]);

  // edge lines
  ctx.fillStyle = 'rgba(255, 196, 92, 0.72)';
  ctx.fillRect(10, 0, 5, h);
  ctx.fillRect(w - 15, 0, 5, h);

  // cracks
  ctx.strokeStyle = 'rgba(8, 5, 9, 0.45)';
  for (let i = 0; i < 26; i++) {
    ctx.lineWidth = rand(0.6, 1.8);
    ctx.beginPath();
    let x = rand(0, w);
    let y = rand(0, h);
    ctx.moveTo(x, y);
    for (let s = 0; s < 5; s++) {
      x += rand(-22, 22);
      y += rand(8, 42);
      ctx.lineTo(x, y);
    }
    ctx.stroke();
  }

  // worn tire tracks
  for (const x of [w * 0.16, w * 0.5, w * 0.84]) {
    const g = ctx.createLinearGradient(x - 40, 0, x + 40, 0);
    g.addColorStop(0, 'rgba(0,0,0,0)');
    g.addColorStop(0.5, 'rgba(0,0,0,0.16)');
    g.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = g;
    ctx.fillRect(x - 40, 0, 80, h);
  }

  return textureFrom(c, { repeatX: 1, repeatY: 26 });
}

export function makeSidewalkTexture() {
  const c = makeCanvas(256, 256);
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#6e5d55';
  ctx.fillRect(0, 0, 256, 256);
  noise(ctx, 256, 256, 1500, 0.09);
  ctx.strokeStyle = 'rgba(30, 22, 26, 0.55)';
  ctx.lineWidth = 3;
  for (let x = 0; x <= 256; x += 64) {
    ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, 256); ctx.stroke();
  }
  for (let y = 0; y <= 256; y += 64) {
    ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(256, y); ctx.stroke();
  }
  ctx.fillStyle = 'rgba(24, 16, 20, 0.18)';
  for (let i = 0; i < 18; i++) ctx.fillRect(rand(0, 256), rand(0, 256), rand(4, 18), rand(4, 18));
  return textureFrom(c, { repeatX: 2, repeatY: 40 });
}

const FACADE_PALETTE = [
  ['#a8625a', '#7c4039'],
  ['#4f7f79', '#345852'],
  ['#b58a58', '#82603a'],
  ['#8e7694', '#5f4b66'],
  ['#c2a986', '#8f7658'],
  ['#7d8f74', '#58694f'],
  ['#9a5a48', '#6c3a2c'],
  ['#6b7c95', '#4a576c'],
];

export function makeFacadeTexture(variant = 0) {
  const w = 256;
  const h = 512;
  const c = makeCanvas(w, h);
  const e = makeCanvas(w, h);
  const ctx = c.getContext('2d');
  const ectx = e.getContext('2d');
  const [base, dark] = FACADE_PALETTE[variant % FACADE_PALETTE.length];
  ectx.fillStyle = '#000';
  ectx.fillRect(0, 0, w, h);

  const g = ctx.createLinearGradient(0, 0, 0, h);
  g.addColorStop(0, base);
  g.addColorStop(0.65, dark);
  g.addColorStop(1, '#2c2027');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, w, h);
  noise(ctx, w, h, 4200, 0.08);

  // concrete banding
  ctx.fillStyle = 'rgba(255, 240, 214, 0.055)';
  for (let y = 30; y < h; y += 64) ctx.fillRect(0, y, w, 5);

  const cols = 4;
  const rows = 10;
  const cellW = w / cols;
  const cellH = (h - 30) / rows;

  for (let row = 0; row < rows; row++) {
    for (let col = 0; col < cols; col++) {
      const x = col * cellW + 15;
      const y = 24 + row * cellH + 12;
      const ww = cellW - 30;
      const wh = cellH - 26;
      const lit = Math.random() < 0.34;
      ctx.fillStyle = lit ? (Math.random() > 0.5 ? '#ffc978' : '#ffdda1') : '#161a24';
      ctx.fillRect(x, y, ww, wh);
      if (lit) {
        ectx.fillStyle = Math.random() > 0.35 ? '#ffb45e' : '#ffe6b0';
        ectx.fillRect(x, y, ww, wh);
      }
      // window frame
      ctx.strokeStyle = 'rgba(15, 10, 14, 0.6)';
      ctx.lineWidth = 3;
      ctx.strokeRect(x, y, ww, wh);
      ctx.fillStyle = 'rgba(20, 14, 18, 0.5)';
      ctx.fillRect(x + ww / 2 - 1, y, 2, wh);
      // grill / balcony on some
      if (row % 3 === 1) {
        ctx.fillStyle = 'rgba(24, 18, 22, 0.8)';
        ctx.fillRect(x - 6, y + wh + 3, ww + 12, 5);
        ctx.strokeStyle = 'rgba(255, 244, 222, 0.12)';
        ctx.lineWidth = 1.5;
        for (let bx = x - 2; bx < x + ww + 2; bx += 8) {
          ctx.beginPath(); ctx.moveTo(bx, y + wh - 14); ctx.lineTo(bx, y + wh + 3); ctx.stroke();
        }
      }
      // AC unit
      if (Math.random() < 0.14) {
        ctx.fillStyle = '#c9c1b2';
        ctx.fillRect(x + ww - 24, y + wh + 8, 22, 14);
        ctx.fillStyle = 'rgba(20, 14, 18, 0.5)';
        ctx.fillRect(x + ww - 22, y + wh + 11, 18, 3);
      }
    }
  }

  // grime streaks
  for (let i = 0; i < 16; i++) {
    const x = rand(0, w);
    const grad = ctx.createLinearGradient(0, 0, 0, h);
    grad.addColorStop(0, 'rgba(20, 14, 18, 0.02)');
    grad.addColorStop(1, 'rgba(20, 14, 18, 0.24)');
    ctx.fillStyle = grad;
    ctx.fillRect(x, rand(0, 80), rand(2, 8), h);
  }

  // rooftop parapet
  ctx.fillStyle = 'rgba(16, 11, 16, 0.55)';
  ctx.fillRect(0, 0, w, 12);

  return {
    map: textureFrom(c, { repeatX: 1, repeatY: 1 }),
    emissiveMap: textureFrom(e, { repeatX: 1, repeatY: 1 }),
  };
}

export function makeSignTexture(text, { bg = '#131a2a', fg = '#ffcf6e', accent = '#ff5a36', vertical = false } = {}) {
  const w = vertical ? 128 : 512;
  const h = vertical ? 512 : 160;
  const c = makeCanvas(w, h);
  const ctx = c.getContext('2d');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, w, h);
  const glow = ctx.createRadialGradient(w / 2, h / 2, 10, w / 2, h / 2, w * 0.7);
  glow.addColorStop(0, 'rgba(255, 255, 255, 0.1)');
  glow.addColorStop(1, 'rgba(0, 0, 0, 0.2)');
  ctx.fillStyle = glow;
  ctx.fillRect(0, 0, w, h);

  ctx.strokeStyle = accent;
  ctx.lineWidth = vertical ? 8 : 7;
  ctx.strokeRect(8, 8, w - 16, h - 16);
  ctx.strokeStyle = 'rgba(255, 244, 222, 0.3)';
  ctx.lineWidth = 2;
  ctx.strokeRect(18, 18, w - 36, h - 36);

  ctx.fillStyle = fg;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.shadowColor = fg;
  ctx.shadowBlur = 18;

  if (vertical) {
    const chars = [...text];
    const size = Math.min(64, (h - 60) / chars.length);
    ctx.font = `700 ${size}px ${BENGALI_FONT}`;
    chars.forEach((ch, i) => {
      ctx.fillText(ch, w / 2, 40 + size * (i + 0.5) + (h - 60 - size * chars.length) / 2);
    });
  } else {
    let size = 78;
    ctx.font = `700 ${size}px ${BENGALI_FONT}`;
    while (ctx.measureText(text).width > w - 60 && size > 26) {
      size -= 4;
      ctx.font = `700 ${size}px ${BENGALI_FONT}`;
    }
    ctx.fillText(text, w / 2, h / 2 + 4);
  }

  return textureFrom(c);
}

export function makeRickshawArtTexture() {
  const s = 512;
  const c = makeCanvas(s, s);
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#8f1f2c';
  ctx.fillRect(0, 0, s, s);

  // sunburst
  ctx.save();
  ctx.translate(s / 2, s / 2);
  for (let i = 0; i < 24; i++) {
    ctx.rotate((Math.PI * 2) / 24);
    ctx.fillStyle = i % 2 ? 'rgba(255, 196, 92, 0.16)' : 'rgba(38, 211, 180, 0.12)';
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(0, -s);
    ctx.lineTo(34, -s);
    ctx.closePath();
    ctx.fill();
  }
  ctx.restore();

  // concentric rings
  const rings = [
    [205, '#ffcf6e', 12],
    [176, '#26d3b4', 9],
    [148, '#ff4f87', 7],
    [122, '#ffcf6e', 5],
  ];
  for (const [r, color, width] of rings) {
    ctx.beginPath();
    ctx.arc(s / 2, s / 2, r, 0, Math.PI * 2);
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.stroke();
  }

  // petals
  ctx.save();
  ctx.translate(s / 2, s / 2);
  for (let i = 0; i < 12; i++) {
    ctx.rotate((Math.PI * 2) / 12);
    ctx.beginPath();
    ctx.ellipse(0, -92, 22, 50, 0, 0, Math.PI * 2);
    ctx.fillStyle = i % 2 ? '#ffcf6e' : '#f7f0dc';
    ctx.fill();
    ctx.strokeStyle = 'rgba(60, 10, 20, 0.5)';
    ctx.lineWidth = 2;
    ctx.stroke();
  }
  ctx.restore();

  // center medallion
  ctx.beginPath();
  ctx.arc(s / 2, s / 2, 54, 0, Math.PI * 2);
  ctx.fillStyle = '#122f33';
  ctx.fill();
  ctx.strokeStyle = '#ffcf6e';
  ctx.lineWidth = 6;
  ctx.stroke();
  ctx.fillStyle = '#26d3b4';
  ctx.font = `700 56px ${BENGALI_FONT}`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('ঢাকা', s / 2, s / 2 + 2);

  // corner flourishes
  for (const [x, y, rot] of [[0, 0, 0], [s, 0, Math.PI / 2], [s, s, Math.PI], [0, s, -Math.PI / 2]]) {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(rot);
    ctx.strokeStyle = '#ffcf6e';
    ctx.lineWidth = 5;
    ctx.beginPath();
    ctx.arc(46, 46, 30, 0, Math.PI / 2);
    ctx.stroke();
    ctx.restore();
  }

  return textureFrom(c);
}

export function makeBannerTexture(text = 'সাবধান', sub = 'ধীরে চলুন') {
  const w = 1024;
  const h = 256;
  const c = makeCanvas(w, h);
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#f5e6c8';
  ctx.fillRect(0, 0, w, h);

  // diagonal hazard stripes
  ctx.save();
  ctx.beginPath();
  ctx.rect(0, 0, w, 34);
  ctx.clip();
  for (let x = -40; x < w + 40; x += 48) {
    ctx.fillStyle = '#1b1b22';
    ctx.beginPath();
    ctx.moveTo(x, 0); ctx.lineTo(x + 24, 0); ctx.lineTo(x + 4, 34); ctx.lineTo(x - 20, 34);
    ctx.closePath(); ctx.fill();
  }
  ctx.restore();
  ctx.save();
  ctx.beginPath();
  ctx.rect(0, h - 34, w, 34);
  ctx.clip();
  for (let x = -40; x < w + 40; x += 48) {
    ctx.fillStyle = '#1b1b22';
    ctx.beginPath();
    ctx.moveTo(x, h); ctx.lineTo(x + 24, h); ctx.lineTo(x + 4, h - 34); ctx.lineTo(x - 20, h - 34);
    ctx.closePath(); ctx.fill();
  }
  ctx.restore();

  ctx.fillStyle = '#b4232c';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.font = `700 112px ${BENGALI_FONT}`;
  ctx.fillText(text, w / 2, h / 2 - 8);
  ctx.fillStyle = '#5a2418';
  ctx.font = `600 34px ${BENGALI_FONT}`;
  ctx.fillText(sub, w / 2, h / 2 + 66);

  return textureFrom(c);
}

export function makeBusTexture(primary = '#1f7a4f', secondary = '#ffcf6e', label = 'বাংলা পরিবহন') {
  const w = 1024;
  const h = 512;
  const c = makeCanvas(w, h);
  const ctx = c.getContext('2d');
  ctx.fillStyle = primary;
  ctx.fillRect(0, 0, w, h);
  noise(ctx, w, h, 2400, 0.07);

  // roof
  ctx.fillStyle = 'rgba(255,255,255,0.16)';
  ctx.fillRect(0, 0, w, 46);
  ctx.fillStyle = secondary;
  ctx.fillRect(0, 46, w, 14);
  ctx.fillRect(0, h - 60, w, 22);

  // windows
  for (let i = 0; i < 7; i++) {
    const x = 42 + i * 138;
    ctx.fillStyle = '#182430';
    ctx.fillRect(x, 100, 110, 128);
    ctx.fillStyle = 'rgba(255, 206, 128, 0.22)';
    ctx.fillRect(x + 6, 106, 98, 40);
    ctx.strokeStyle = 'rgba(10, 8, 12, 0.6)';
    ctx.lineWidth = 6;
    ctx.strokeRect(x, 100, 110, 128);
  }

  // destination board
  ctx.fillStyle = '#10151e';
  ctx.fillRect(250, 262, 520, 60);
  ctx.fillStyle = '#ffd166';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.font = `600 40px ${BENGALI_FONT}`;
  ctx.fillText(label, 510, 294);

  // stripes
  ctx.fillStyle = secondary;
  ctx.fillRect(0, 350, w, 26);
  ctx.fillStyle = '#e8452f';
  ctx.fillRect(0, 384, w, 12);

  // wheels shadows
  ctx.fillStyle = 'rgba(0,0,0,0.45)';
  ctx.beginPath(); ctx.ellipse(210, 470, 100, 44, 0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(810, 470, 100, 44, 0, 0, Math.PI * 2); ctx.fill();

  // grime
  for (let i = 0; i < 12; i++) {
    ctx.fillStyle = `rgba(20, 14, 18, ${rand(0.03, 0.1)})`;
    ctx.fillRect(rand(0, w), rand(300, h), rand(20, 90), rand(10, 50));
  }

  return textureFrom(c);
}

export function makeShopTexture(text, bg = '#ff5a36', fg = '#fff4de') {
  const w = 512;
  const h = 128;
  const c = makeCanvas(w, h);
  const ctx = c.getContext('2d');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, w, h);
  ctx.strokeStyle = 'rgba(255, 244, 222, 0.4)';
  ctx.lineWidth = 4;
  ctx.strokeRect(6, 6, w - 12, h - 12);
  ctx.fillStyle = fg;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.font = `700 56px ${BENGALI_FONT}`;
  ctx.fillText(text, w / 2, h / 2 + 2);
  return textureFrom(c);
}

export function makeGlowTexture() {
  const s = 128;
  const c = makeCanvas(s, s);
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(s / 2, s / 2, 0, s / 2, s / 2, s / 2);
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(0.18, 'rgba(255,236,190,0.8)');
  g.addColorStop(0.45, 'rgba(255,150,60,0.25)');
  g.addColorStop(1, 'rgba(255,120,40,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, s, s);
  return textureFrom(c);
}

export function makeCloudTexture() {
  const w = 512;
  const h = 256;
  const c = makeCanvas(w, h);
  const ctx = c.getContext('2d');
  for (let i = 0; i < 26; i++) {
    const x = rand(60, w - 60);
    const y = rand(70, h - 70);
    const r = rand(26, 74);
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, `rgba(255, 214, 176, ${rand(0.05, 0.16)})`);
    g.addColorStop(1, 'rgba(255, 214, 176, 0)');
    ctx.fillStyle = g;
    ctx.fillRect(x - r, y - r, r * 2, r * 2);
  }
  return textureFrom(c);
}

export function makeSkylineTexture() {
  const w = 1024;
  const h = 256;
  const c = makeCanvas(w, h);
  const ctx = c.getContext('2d');
  ctx.clearRect(0, 0, w, h);
  ctx.fillStyle = '#2b1c33';
  let x = 0;
  while (x < w) {
    const bw = rand(26, 90);
    const bh = rand(50, 220);
    ctx.fillRect(x, h - bh, bw, bh);
    ctx.fillStyle = 'rgba(255, 196, 120, 0.5)';
    for (let wy = h - bh + 12; wy < h - 8; wy += 18) {
      for (let wx = x + 7; wx < x + bw - 6; wx += 14) {
        if (Math.random() < 0.35) ctx.fillRect(wx, wy, 4, 6);
      }
    }
    ctx.fillStyle = '#2b1c33';
    x += bw + rand(2, 12);
  }
  return textureFrom(c);
}

export function makeMangoLeafTexture() {
  const c = makeCanvas(64, 64);
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#2f8f4e';
  ctx.beginPath();
  ctx.ellipse(32, 32, 14, 30, Math.PI / 4, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = '#1d6b37';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(22, 42); ctx.lineTo(42, 22);
  ctx.stroke();
  return textureFrom(c);
}

import * as THREE from 'three';
import { makeRickshawArtTexture, makeGlowTexture } from './textures.js';

const SKIN = 0x9a6440;

function std(color, opts = {}) {
  return new THREE.MeshStandardMaterial({ color, roughness: 0.62, metalness: 0.08, ...opts });
}

function addMesh(parent, geometry, material, position = [0, 0, 0], rotation = [0, 0, 0]) {
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(...position);
  mesh.rotation.set(...rotation);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  parent.add(mesh);
  return mesh;
}

function makeWheel(radius = 0.44) {
  const wheel = new THREE.Group();
  const tireMat = new THREE.MeshStandardMaterial({ color: 0x16121a, roughness: 0.9, metalness: 0.02 });
  const rimMat = new THREE.MeshStandardMaterial({ color: 0xd8b26a, roughness: 0.4, metalness: 0.55 });
  const tire = new THREE.Mesh(new THREE.TorusGeometry(radius, 0.085, 10, 22), tireMat);
  tire.rotation.y = Math.PI / 2;
  tire.castShadow = true;
  wheel.add(tire);

  const rim = new THREE.Mesh(new THREE.TorusGeometry(radius * 0.72, 0.022, 6, 20), rimMat);
  rim.rotation.y = Math.PI / 2;
  wheel.add(rim);

  const hub = new THREE.Mesh(new THREE.CylinderGeometry(0.09, 0.09, 0.16, 12), rimMat);
  hub.rotation.z = Math.PI / 2;
  wheel.add(hub);

  const spokeGeo = new THREE.CylinderGeometry(0.012, 0.012, radius * 1.4, 5);
  for (let i = 0; i < 8; i++) {
    const angle = (i / 8) * Math.PI * 2;
    const spoke = new THREE.Mesh(spokeGeo, rimMat);
    spoke.position.set(0, Math.cos(angle) * radius * 0.34, Math.sin(angle) * radius * 0.34);
    spoke.rotation.x = angle;
    wheel.add(spoke);
  }
  return wheel;
}

export function createRickshaw() {
  const root = new THREE.Group();
  const body = new THREE.Group();
  root.add(body);

  const artTexture = makeRickshawArtTexture();
  const artMat = new THREE.MeshStandardMaterial({ map: artTexture, roughness: 0.55, metalness: 0.05, side: THREE.DoubleSide });
  const crimson = std(0xb3263b, { roughness: 0.48 });
  const crimsonDark = std(0x7d1728, { roughness: 0.55 });
  const teal = std(0x169e8c, { roughness: 0.5 });
  const tealDark = std(0x0d6b60, { roughness: 0.55 });
  const gold = std(0xe0b45f, { roughness: 0.35, metalness: 0.45 });
  const black = std(0x1a1519, { roughness: 0.8 });
  const cream = std(0xf4dfb8, { roughness: 0.7 });
  const cushion = std(0x8f1f35, { roughness: 0.85 });

  // ---- chassis ----
  addMesh(body, new THREE.BoxGeometry(1.3, 0.14, 2.45), crimsonDark, [0, 0.54, 0.05]);
  addMesh(body, new THREE.BoxGeometry(1.44, 0.1, 2.15), crimson, [0, 0.64, 0.12]);
  addMesh(body, new THREE.BoxGeometry(1.5, 0.06, 0.5), gold, [0, 0.67, -0.92]);
  // footboard
  addMesh(body, new THREE.BoxGeometry(1.42, 0.09, 0.5), tealDark, [0, 0.74, -1.12]);

  // ---- seat ----
  addMesh(body, new THREE.BoxGeometry(1.28, 0.2, 1.0), cream, [0, 0.96, 0.48]);
  addMesh(body, new THREE.BoxGeometry(1.2, 0.13, 0.92), cushion, [0, 1.07, 0.48]);
  const backrest = addMesh(body, new THREE.BoxGeometry(1.28, 0.78, 0.18), crimson, [0, 1.42, 0.97]);
  backrest.rotation.x = -0.1;
  addMesh(body, new THREE.BoxGeometry(1.18, 0.55, 0.08), cushion, [0, 1.42, 0.87], [-0.1, 0, 0]);

  // rear panel with art
  addMesh(body, new THREE.BoxGeometry(1.28, 0.62, 0.05), crimsonDark, [0, 0.86, 1.22]);
  const rearArt = addMesh(body, new THREE.PlaneGeometry(1.1, 0.5), artMat, [0, 0.88, 1.253]);
  rearArt.rotation.y = 0;

  // side art panels
  for (const side of [-1, 1]) {
    const panel = addMesh(body, new THREE.PlaneGeometry(1.72, 0.62), artMat, [side * 0.735, 0.9, 0.28], [0, side * Math.PI / 2, 0]);
    panel.castShadow = false;
    // fender rail
    addMesh(body, new THREE.BoxGeometry(0.05, 0.05, 1.95), gold, [side * 0.74, 1.24, 0.2]);
  }

  // ---- canopy ----
  const shape = new THREE.Shape();
  shape.moveTo(-0.86, 0);
  shape.quadraticCurveTo(-0.86, 0.86, 0, 1.04);
  shape.quadraticCurveTo(0.86, 0.86, 0.86, 0);
  shape.lineTo(-0.86, 0);
  const canopyGeo = new THREE.ExtrudeGeometry(shape, {
    depth: 2.1,
    bevelEnabled: true,
    bevelSize: 0.035,
    bevelThickness: 0.035,
    bevelSegments: 2,
    curveSegments: 14,
  });
  const canopy = new THREE.Mesh(canopyGeo, new THREE.MeshStandardMaterial({
    color: 0xa82137,
    roughness: 0.5,
    metalness: 0.04,
    side: THREE.DoubleSide,
  }));
  canopy.position.set(0, 1.38, -1.02);
  canopy.castShadow = true;
  body.add(canopy);

  // canopy lining
  const lining = new THREE.Mesh(canopyGeo, new THREE.MeshStandardMaterial({
    color: 0x2a8c7f,
    roughness: 0.7,
    side: THREE.BackSide,
  }));
  lining.scale.set(0.965, 0.965, 0.98);
  lining.position.copy(canopy.position);
  body.add(lining);

  // scalloped fringe
  const fringeMat = new THREE.MeshStandardMaterial({ color: 0xffcf6e, roughness: 0.5 });
  const fringeGeo = new THREE.SphereGeometry(0.058, 8, 6);
  for (const z of [-1.02, 1.06]) {
    for (let i = 0; i < 13; i++) {
      const t = i / 12;
      const x = -0.8 + t * 1.6;
      const y = 1.38 + Math.sin(t * Math.PI) * 0.86 + 0.02;
      const bead = new THREE.Mesh(fringeGeo, i % 2 ? fringeMat : teal);
      bead.position.set(x, y, z);
      bead.scale.y = 1.5;
      body.add(bead);
    }
  }

  // canopy support poles
  for (const x of [-0.8, 0.8]) {
    for (const z of [-0.95, 0.95]) {
      addMesh(body, new THREE.CylinderGeometry(0.025, 0.025, 0.92, 6), gold, [x, 1.16, z]);
    }
  }

  // ---- front / handlebar ----
  const handle = addMesh(body, new THREE.CylinderGeometry(0.026, 0.026, 1.08, 8), black, [0, 1.24, -1.28], [0, 0, Math.PI / 2]);
  handle.castShadow = true;
  addMesh(body, new THREE.CylinderGeometry(0.03, 0.03, 0.55, 8), gold, [0, 1.02, -1.22], [0.18, 0, 0]);
  addMesh(body, new THREE.BoxGeometry(0.5, 0.16, 0.08), black, [0, 1.02, -1.4]);

  // headlamp
  const lamp = new THREE.Mesh(new THREE.SphereGeometry(0.11, 12, 10), new THREE.MeshStandardMaterial({
    color: 0xfff2c9,
    emissive: 0xffd27a,
    emissiveIntensity: 3,
    roughness: 0.3,
  }));
  lamp.position.set(0, 0.94, -1.46);
  body.add(lamp);
  const lampGlow = new THREE.Sprite(new THREE.SpriteMaterial({
    map: makeGlowTexture(),
    color: 0xffd27a,
    transparent: true,
    opacity: 0.75,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
  }));
  lampGlow.scale.set(1.15, 1.15, 1);
  lampGlow.position.copy(lamp.position);
  body.add(lampGlow);

  // bell
  const bell = addMesh(body, new THREE.SphereGeometry(0.07, 10, 8), gold, [0.4, 1.31, -1.24]);
  bell.scale.y = 0.9;
  addMesh(body, new THREE.CylinderGeometry(0.012, 0.012, 0.1, 5), gold, [0.4, 1.38, -1.24]);

  // rear reflectors
  for (const x of [-0.55, 0.55]) {
    const r = new THREE.Mesh(new THREE.SphereGeometry(0.055, 8, 6), new THREE.MeshStandardMaterial({
      color: 0xff3b2f,
      emissive: 0xff2a1c,
      emissiveIntensity: 2.2,
    }));
    r.position.set(x, 1.1, 1.26);
    body.add(r);
  }

  // ---- driver ----
  const driver = new THREE.Group();
  driver.position.set(0, 0, 0);
  body.add(driver);
  const torso = addMesh(driver, new THREE.CapsuleGeometry(0.2, 0.34, 6, 12), std(0xd77a2c, { roughness: 0.8 }), [0, 1.34, -0.52], [0.22, 0, 0]);
  torso.castShadow = true;
  const head = addMesh(driver, new THREE.SphereGeometry(0.16, 16, 12), std(SKIN, { roughness: 0.75 }), [0, 1.72, -0.58]);
  head.castShadow = true;
  // cap
  addMesh(driver, new THREE.SphereGeometry(0.168, 14, 8, 0, Math.PI * 2, 0, Math.PI / 2), std(0xe8ddc4, { roughness: 0.8 }), [0, 1.75, -0.58]);
  addMesh(driver, new THREE.CylinderGeometry(0.19, 0.19, 0.035, 14), std(0xe8ddc4), [0, 1.76, -0.64]);
  // arms
  for (const side of [-1, 1]) {
    const arm = addMesh(driver, new THREE.CylinderGeometry(0.055, 0.06, 0.62, 7), std(SKIN, { roughness: 0.8 }), [side * 0.25, 1.3, -0.92], [1.16, 0, side * 0.16]);
    arm.castShadow = true;
  }
  // legs
  for (const side of [-1, 1]) {
    addMesh(driver, new THREE.CylinderGeometry(0.075, 0.07, 0.55, 7), std(0x2c3b56, { roughness: 0.85 }), [side * 0.2, 0.96, -0.78], [1.2, 0, 0]);
  }

  // ---- passenger ----
  const passenger = new THREE.Group();
  passenger.position.set(0, 0, 0.42);
  body.add(passenger);
  addMesh(passenger, new THREE.CapsuleGeometry(0.21, 0.32, 6, 12), std(0xc94f7c, { roughness: 0.85 }), [0, 1.34, 0], [-0.08, 0, 0]);
  addMesh(passenger, new THREE.SphereGeometry(0.155, 14, 12), std(0x8a5735, { roughness: 0.78 }), [0, 1.7, 0.02]);
  addMesh(passenger, new THREE.SphereGeometry(0.163, 12, 8, 0, Math.PI * 2, 0, Math.PI * 0.62), std(0x1a1216, { roughness: 0.9 }), [0, 1.73, 0.02]);
  // saree drape
  const drape = addMesh(passenger, new THREE.ConeGeometry(0.33, 0.6, 10, 1, true), std(0xe4a33b, { roughness: 0.85, side: THREE.DoubleSide }), [0, 1.08, 0.02]);
  drape.scale.z = 0.8;

  // ---- wheels ----
  const wheels = [];
  const wheelSpecs = [
    [-0.72, 0.45, 0.98],
    [0.72, 0.45, 0.98],
    [0, 0.45, -1.18],
  ];
  for (const [x, y, z] of wheelSpecs) {
    const wheel = makeWheel(0.44);
    wheel.position.set(x, y, z);
    root.add(wheel);
    wheels.push(wheel);
  }
  // front fork
  addMesh(body, new THREE.CylinderGeometry(0.035, 0.035, 0.75, 7), gold, [0, 0.75, -1.18], [0.12, 0, 0]);

  // subtle rim light from below
  const under = new THREE.PointLight(0xff7a3a, 0.55, 5, 2);
  under.position.set(0, 0.28, 0.6);
  root.add(under);

  root.traverse((obj) => {
    if (obj.isMesh) {
      obj.castShadow = obj.castShadow !== false;
      obj.receiveShadow = true;
    }
  });

  const state = {
    wheelSpin: 0,
    bob: 0,
    lean: 0,
    duck: 0,
    boost: 0,
    time: 0,
  };

  function update(dt, { speed = 0, lean = 0, duck = 0, boost = 0, airborne = false, vy = 0, crashed = false } = {}) {
    state.time += dt;
    state.wheelSpin += (speed * dt) / 0.44;
    state.lean += (lean - state.lean) * Math.min(1, dt * 8);
    state.duck += (duck - state.duck) * Math.min(1, dt * 12);
    state.boost += (boost - state.boost) * Math.min(1, dt * 6);

    for (const wheel of wheels) wheel.rotation.x = -state.wheelSpin;

    const bobAmp = airborne ? 0 : 0.018 + Math.min(speed, 40) * 0.0007;
    state.bob = Math.sin(state.time * (7 + speed * 0.14)) * bobAmp;
    body.position.y = state.bob;
    body.rotation.z = -state.lean * 0.2;
    body.rotation.x = airborne ? THREE.MathUtils.clamp(-vy * 0.018, -0.16, 0.2) : Math.sin(state.time * 5.4) * 0.004;
    body.scale.y = 1 - state.duck * 0.26;
    body.scale.x = 1 + state.duck * 0.06;

    driver.rotation.z = -state.lean * 0.14;
    driver.rotation.x = state.duck * 0.3;
    passenger.rotation.z = -state.lean * 0.1;
    passenger.position.y = state.duck * -0.05;

    lampGlow.material.opacity = 0.65 + Math.sin(state.time * 9) * 0.05;
    lampGlow.scale.setScalar(1.05 + state.boost * 0.5);
    under.intensity = 0.45 + state.boost * 1.6;

    if (crashed) {
      body.rotation.z = Math.sin(state.time * 18) * 0.12 - 0.25;
    }
  }

  return { root, update, body, wheels, driver, passenger };
}

import * as THREE from 'three';
import {
  makeRoadTexture,
  makeSidewalkTexture,
  makeFacadeTexture,
  makeSignTexture,
  makeBannerTexture,
  makeBusTexture,
  makeShopTexture,
  makeGlowTexture,
  makeCloudTexture,
  makeSkylineTexture,
  makeMangoLeafTexture,
} from './textures.js';

export const LANES = [-2.6, 0, 2.6];
const SPAWN_Z = -205;
const DESPAWN_Z = 28;
const CITY_SPAN = 300;
const ROAD_LENGTH = 620;

const BUS_LABELS = ['বাংলা পরিবহন', 'ঢাকা মেট্রো', 'সুন্দরবন এক্সপ্রেস', 'বিক্রমপুর'];
const SIGN_TEXTS = ['চা ঘর', 'মিষ্টি', 'রিকশা গ্যারেজ', 'বিরিয়ানি', 'সেলুন', 'বইঘর', 'ফার্মেসি', 'জামা কাপড়'];
const SIGN_COLORS = [
  ['#10202c', '#ffcf6e', '#ff5a36'],
  ['#2a1020', '#ff9fc4', '#ffcf6e'],
  ['#0f2420', '#7dffd8', '#26d3b4'],
  ['#241a0f', '#ffe9a8', '#ff8a3c'],
];

function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }
function rand(a, b) { return a + Math.random() * (b - a); }
function pick(arr) { return arr[(Math.random() * arr.length) | 0]; }

function std(color, opts = {}) {
  return new THREE.MeshStandardMaterial({ color, roughness: 0.72, metalness: 0.06, ...opts });
}

function mesh(parent, geometry, material, position = [0, 0, 0], rotation = [0, 0, 0], cast = false) {
  const m = new THREE.Mesh(geometry, material);
  m.position.set(...position);
  m.rotation.set(...rotation);
  m.castShadow = cast;
  m.receiveShadow = true;
  parent.add(m);
  return m;
}

export class World {
  constructor(scene, { quality = 'high', callbacks = {} } = {}) {
    this.scene = scene;
    this.callbacks = callbacks;
    this.quality = quality;
    this.time = 0;
    this.night = 0;
    this.speed = 0;
    this.city = [];
    this.props = [];
    this.obstacles = [];
    this.mangoes = [];
    this.pools = {};
    this.spawnTimer = 1.2;
    this.waveIndex = 0;
    this.roadTexture = makeRoadTexture();
    this.sidewalkTexture = makeSidewalkTexture();
    this.glowTexture = makeGlowTexture();
    this.mangoLeafTexture = makeMangoLeafTexture();
    this.facades = Array.from({ length: 8 }, (_, i) => makeFacadeTexture(i));
    this.facadeMats = this.facades.map(({ map, emissiveMap }) => new THREE.MeshStandardMaterial({
      map,
      emissiveMap,
      emissive: 0xffb264,
      emissiveIntensity: 0.65,
      roughness: 0.88,
      metalness: 0.02,
    }));
    this.neonMats = [];
    this.traffic = [];
    this._tmp = new THREE.Vector3();

    this.buildSky();
    this.buildLights();
    this.buildGround();
    this.buildCity();
    this.buildStreetFurniture();
    this.buildTeaStall();
    this.buildParticles();
    this.buildAmbient();
    this.spawnInitial();
  }

  /* ------------------------------------------------------------------ sky */

  buildSky() {
    const geometry = new THREE.SphereGeometry(430, 32, 20);
    this.skyMaterial = new THREE.ShaderMaterial({
      side: THREE.BackSide,
      depthWrite: false,
      uniforms: {
        topColor: { value: new THREE.Color(0x2b1b4a) },
        horizonColor: { value: new THREE.Color(0xffa46b) },
        bottomColor: { value: new THREE.Color(0x4a2735) },
        sunColor: { value: new THREE.Color(0xffd7a0) },
        sunDir: { value: new THREE.Vector3(-0.45, 0.16, -0.88).normalize() },
      },
      vertexShader: `
        varying vec3 vDir;
        void main() {
          vDir = normalize(position);
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        uniform vec3 topColor;
        uniform vec3 horizonColor;
        uniform vec3 bottomColor;
        uniform vec3 sunColor;
        uniform vec3 sunDir;
        varying vec3 vDir;
        void main() {
          vec3 dir = normalize(vDir);
          float h = dir.y;
          vec3 col = mix(horizonColor, topColor, smoothstep(-0.02, 0.62, h));
          col = mix(bottomColor, col, smoothstep(-0.28, 0.02, h));
          float d = max(dot(dir, normalize(sunDir)), 0.0);
          col += sunColor * pow(d, 6.0) * 0.32;
          col += sunColor * pow(d, 120.0) * 1.1;
          gl_FragColor = vec4(col, 1.0);
        }
      `,
    });
    this.sky = new THREE.Mesh(geometry, this.skyMaterial);
    this.sky.frustumCulled = false;
    this.scene.add(this.sky);

    const sun = new THREE.Sprite(new THREE.SpriteMaterial({
      map: this.glowTexture,
      color: 0xffe0ae,
      transparent: true,
      opacity: 0.95,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      fog: false,
    }));
    sun.position.set(-150, 44, -360);
    sun.scale.set(210, 210, 1);
    this.scene.add(sun);
    this.sun = sun;

    const cloudTex = makeCloudTexture();
    this.clouds = [];
    for (let i = 0; i < 9; i++) {
      const cloud = new THREE.Sprite(new THREE.SpriteMaterial({
        map: cloudTex,
        color: 0xffc8a0,
        transparent: true,
        opacity: rand(0.25, 0.55),
        depthWrite: false,
        fog: false,
      }));
      cloud.position.set(rand(-280, 280), rand(38, 105), rand(-400, -220));
      cloud.scale.set(rand(120, 260), rand(50, 100), 1);
      this.scene.add(cloud);
      this.clouds.push(cloud);
    }

    const skylineTex = makeSkylineTexture();
    for (const [z, y, scale, opacity] of [[-310, 26, 1.6, 0.55], [-260, 18, 1.15, 0.75]]) {
      const skyline = new THREE.Mesh(
        new THREE.PlaneGeometry(620, 90),
        new THREE.MeshBasicMaterial({ map: skylineTex, transparent: true, opacity, depthWrite: false, fog: false })
      );
      skyline.position.set(0, y, z);
      skyline.scale.set(scale, 1, 1);
      this.scene.add(skyline);
    }

    this.scene.fog = new THREE.FogExp2(0xd9895e, 0.0058);
  }

  buildLights() {
    this.hemi = new THREE.HemisphereLight(0xffc296, 0x2c1b2c, 1.15);
    this.scene.add(this.hemi);

    this.sunLight = new THREE.DirectionalLight(0xffc08a, 2.5);
    this.sunLight.position.set(-45, 62, -35);
    this.sunLight.castShadow = true;
    const shadowSize = this.quality === 'low' ? 1024 : 2048;
    this.sunLight.shadow.mapSize.set(shadowSize, shadowSize);
    this.sunLight.shadow.camera.left = -26;
    this.sunLight.shadow.camera.right = 26;
    this.sunLight.shadow.camera.top = 30;
    this.sunLight.shadow.camera.bottom = -20;
    this.sunLight.shadow.camera.near = 1;
    this.sunLight.shadow.camera.far = 170;
    this.sunLight.shadow.bias = -0.0008;
    this.sunLight.shadow.normalBias = 0.03;
    this.scene.add(this.sunLight);
    this.scene.add(this.sunLight.target);
    this.sunLight.target.position.set(0, 0, -12);

    this.fill = new THREE.DirectionalLight(0x8a6cff, 0.45);
    this.fill.position.set(30, 18, 40);
    this.scene.add(this.fill);

    this.scene.add(new THREE.AmbientLight(0x5a3a4a, 0.35));
  }

  /* --------------------------------------------------------------- ground */

  buildGround() {
    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(420, ROAD_LENGTH + 120),
      new THREE.MeshStandardMaterial({ color: 0x241a22, roughness: 1 })
    );
    ground.rotation.x = -Math.PI / 2;
    ground.position.set(0, -0.04, -ROAD_LENGTH / 2 + 80);
    ground.receiveShadow = true;
    this.scene.add(ground);

    this.road = new THREE.Mesh(
      new THREE.PlaneGeometry(10.6, ROAD_LENGTH),
      new THREE.MeshStandardMaterial({ map: this.roadTexture, roughness: 0.94, metalness: 0.03 })
    );
    this.road.rotation.x = -Math.PI / 2;
    this.road.position.set(0, 0, -ROAD_LENGTH / 2 + 80);
    this.road.receiveShadow = true;
    this.scene.add(this.road);

    const sidewalkMat = new THREE.MeshStandardMaterial({ map: this.sidewalkTexture, roughness: 0.95 });
    for (const side of [-1, 1]) {
      const walk = new THREE.Mesh(new THREE.PlaneGeometry(3.4, ROAD_LENGTH), sidewalkMat);
      walk.rotation.x = -Math.PI / 2;
      walk.position.set(side * 7.05, 0.14, -ROAD_LENGTH / 2 + 80);
      walk.receiveShadow = true;
      this.scene.add(walk);

      const curbMat = std(0x8a7668, { roughness: 0.9 });
      const curb = mesh(this.scene, new THREE.BoxGeometry(0.32, 0.3, ROAD_LENGTH), curbMat, [side * 5.36, 0.15, -ROAD_LENGTH / 2 + 80]);
      curb.receiveShadow = true;

      const rail = mesh(this.scene, new THREE.BoxGeometry(0.1, 0.1, ROAD_LENGTH), std(0x3a2d33, { metalness: 0.4, roughness: 0.5 }), [side * 8.78, 1.05, -ROAD_LENGTH / 2 + 80]);
      rail.castShadow = false;
    }
  }

  /* ----------------------------------------------------------------- city */

  buildCity() {
    const perSide = 16;
    const spacing = CITY_SPAN / perSide;
    for (const side of [-1, 1]) {
      for (let i = 0; i < perSide; i++) {
        const group = new THREE.Group();
        const z = 40 - i * spacing - rand(0, 4);
        const depth = rand(8, 15);
        const width = rand(7, 12);
        const height = rand(9, 30);
        group.position.set(side * (9.6 + width / 2 + rand(0, 1.6)), 0, z);

        const variant = (Math.random() * this.facades.length) | 0;
        const facadeMat = this.facadeMats[variant];
        const wallMat = new THREE.MeshStandardMaterial({
          color: this.facades[variant].map.image ? 0x8a6a5c : 0x7a5a50,
          roughness: 0.95,
        });

        const body = new THREE.Mesh(new THREE.BoxGeometry(width, height, depth), [
          facadeMat, facadeMat,
          std(0x2c2229, { roughness: 0.95 }),
          std(0x1c151a, { roughness: 1 }),
          wallMat, wallMat,
        ]);
        body.position.y = height / 2;
        body.receiveShadow = true;
        group.add(body);

        // rooftop clutter
        if (Math.random() < 0.85) {
          const tank = mesh(group, new THREE.CylinderGeometry(rand(0.5, 0.9), rand(0.5, 0.9), rand(0.8, 1.4), 10), std(0x1d2830, { roughness: 0.8 }), [rand(-width * 0.25, width * 0.25), height + 0.6, rand(-depth * 0.2, depth * 0.2)]);
          tank.castShadow = false;
        }
        if (Math.random() < 0.55) {
          const ac = mesh(group, new THREE.BoxGeometry(rand(0.7, 1.2), rand(0.5, 0.8), rand(0.6, 1.1)), std(0xb8ab9a, { roughness: 0.9 }), [rand(-width * 0.3, width * 0.3), height + 0.3, rand(-depth * 0.3, depth * 0.3)]);
          ac.castShadow = false;
        }
        if (Math.random() < 0.35) {
          const mast = mesh(group, new THREE.CylinderGeometry(0.03, 0.03, rand(2, 5), 4), std(0x2a2228), [rand(-width * 0.3, width * 0.3), height + 2, rand(-depth * 0.3, depth * 0.3)]);
          mast.castShadow = false;
        }

        // ground floor shop
        if (Math.random() < 0.62) {
          const shopColor = pick(['#ff5a36', '#26d3b4', '#ffcf6e', '#ff4f87', '#4f7fff']);
          const signTex = makeShopTexture(pick(SIGN_TEXTS), shopColor, '#fff4de');
          const signMat = new THREE.MeshStandardMaterial({
            map: signTex,
            emissiveMap: signTex,
            emissive: 0xffffff,
            emissiveIntensity: 1.15,
            roughness: 0.5,
          });
          this.neonMats.push(signMat);
          const sign = new THREE.Mesh(new THREE.PlaneGeometry(rand(2.4, 3.6), 0.85), signMat);
          sign.position.set(-side * (width / 2 + 0.06), 3.35, rand(-depth * 0.28, depth * 0.28));
          sign.rotation.y = side > 0 ? -Math.PI / 2 : Math.PI / 2;
          group.add(sign);

          // awning
          const awning = mesh(
            group,
            new THREE.BoxGeometry(0.9, 0.08, rand(2.2, 3.2)),
            std(pick([0xc23b2f, 0x1f7a63, 0xd9a13b]), { roughness: 0.85 }),
            [-side * (width / 2 + 0.55), 2.9, rand(-depth * 0.2, depth * 0.2)],
            [0, 0, side * 0.16]
          );
          awning.castShadow = false;

          // warm interior glow
          const glow = new THREE.Sprite(new THREE.SpriteMaterial({
            map: this.glowTexture,
            color: 0xffb466,
            transparent: true,
            opacity: 0.45,
            depthWrite: false,
            blending: THREE.AdditiveBlending,
          }));
          glow.position.set(-side * (width / 2 + 0.2), 1.8, rand(-depth * 0.3, depth * 0.3));
          glow.scale.set(4, 3, 1);
          group.add(glow);
        }

        // occasional vertical neon sign
        if (Math.random() < 0.34) {
          const [bg, fg, accent] = pick(SIGN_COLORS);
          const tex = makeSignTexture(pick(['হোটেল', 'চা', 'বাজার', 'ঢাকা']), { bg, fg, accent, vertical: true });
          const mat = new THREE.MeshStandardMaterial({
            map: tex,
            emissiveMap: tex,
            emissive: 0xffffff,
            emissiveIntensity: 1.35,
            roughness: 0.4,
          });
          this.neonMats.push(mat);
          const sign = new THREE.Mesh(new THREE.PlaneGeometry(1.1, 4.4), mat);
          sign.position.set(-side * (width / 2 + 0.08), rand(5.5, 9), -depth * 0.18);
          sign.rotation.y = side > 0 ? -Math.PI / 2 : Math.PI / 2;
          group.add(sign);
        }

        this.scene.add(group);
        this.city.push({ group, baseZ: z, side, height });
      }
    }

    // far background block silhouettes
    for (const side of [-1, 1]) {
      for (let i = 0; i < 10; i++) {
        const w = rand(12, 24);
        const h = rand(20, 52);
        const b = new THREE.Mesh(new THREE.BoxGeometry(w, h, 10), new THREE.MeshBasicMaterial({ color: 0x2a1c32, fog: true }));
        b.position.set(side * rand(30, 70), h / 2, rand(-300, -170));
        this.scene.add(b);
      }
    }
  }

  /* ------------------------------------------------------ street furniture */

  buildStreetFurniture() {
    // lamp posts
    for (const side of [-1, 1]) {
      for (let i = 0; i < 11; i++) {
        const group = new THREE.Group();
        const z = 24 - i * 26 - rand(0, 3);
        group.position.set(side * 8.5, 0, z);
        const poleMat = std(0x2b2229, { metalness: 0.55, roughness: 0.45 });
        mesh(group, new THREE.CylinderGeometry(0.07, 0.11, 5.6, 8), poleMat, [0, 2.8, 0], [0, 0, 0], true);
        mesh(group, new THREE.CylinderGeometry(0.05, 0.05, 1.5, 6), poleMat, [-side * 0.65, 5.5, 0], [0, 0, Math.PI / 2], true);
        const headMat = new THREE.MeshStandardMaterial({
          color: 0xffe6b0,
          emissive: 0xffb45e,
          emissiveIntensity: 2.4,
          roughness: 0.4,
        });
        mesh(group, new THREE.BoxGeometry(0.42, 0.16, 0.28), headMat, [-side * 1.32, 5.42, 0]);
        const halo = new THREE.Sprite(new THREE.SpriteMaterial({
          map: this.glowTexture,
          color: 0xffb45e,
          transparent: true,
          opacity: 0.65,
          depthWrite: false,
          blending: THREE.AdditiveBlending,
        }));
        halo.position.set(-side * 1.32, 5.3, 0);
        halo.scale.set(3.4, 3.4, 1);
        group.add(halo);
        this.scene.add(group);
        this.props.push({ group, baseZ: z, side, kind: 'lamp' });
      }
    }

    // trees
    for (const side of [-1, 1]) {
      for (let i = 0; i < 13; i++) {
        const group = new THREE.Group();
        const z = 8 - i * 22 - rand(0, 4);
        group.position.set(side * rand(9.1, 10.4), 0, z);
        const palm = Math.random() < 0.5;
        if (palm) {
          const trunk = mesh(group, new THREE.CylinderGeometry(0.1, 0.19, rand(4, 6.5), 6), std(0x6b4b36, { roughness: 0.95 }), [0, 2.4, 0], [0, 0, rand(-0.06, 0.06)], true);
          const top = 4.7;
          const frondMat = std(0x2f6b4a, { roughness: 0.85, side: THREE.DoubleSide });
          for (let f = 0; f < 7; f++) {
            const a = (f / 7) * Math.PI * 2;
            const frond = mesh(group, new THREE.ConeGeometry(0.34, 2.5, 4), frondMat, [Math.cos(a) * 0.55, top, Math.sin(a) * 0.55], [Math.sin(a) * 1.15, 0, -Math.cos(a) * 1.15]);
            frond.scale.set(1, 1, 0.25);
            frond.castShadow = false;
          }
          for (let c = 0; c < 3; c++) {
            mesh(group, new THREE.SphereGeometry(0.16, 6, 5), std(0x4a3a22), [rand(-0.3, 0.3), top - 0.4, rand(-0.3, 0.3)]);
          }
        } else {
          mesh(group, new THREE.CylinderGeometry(0.18, 0.28, rand(2.6, 4), 6), std(0x5a4030, { roughness: 0.95 }), [0, 1.6, 0], [0, 0, 0], true);
          const canopyMat = std(pick([0x2d5a3f, 0x386a48, 0x274f3b]), { roughness: 0.9 });
          for (let c = 0; c < 4; c++) {
            const blob = mesh(group, new THREE.SphereGeometry(rand(1.1, 1.8), 7, 5), canopyMat, [rand(-1, 1), rand(3, 4.4), rand(-1, 1)]);
            blob.castShadow = false;
          }
        }
        this.scene.add(group);
        this.props.push({ group, baseZ: z, side, kind: 'tree' });
      }
    }

    // cows resting on sidewalks
    for (const side of [-1, 1]) {
      for (let i = 0; i < 3; i++) {
        const cow = this.createCow();
        cow.position.set(side * rand(9.4, 10.6), 0, 10 - i * 60 - rand(0, 12));
        cow.rotation.y = rand(0, Math.PI * 2);
        cow.scale.setScalar(0.85);
        this.scene.add(cow);
        this.props.push({ group: cow, baseZ: cow.position.z, side, kind: 'cow' });
      }
    }

    // banners over the road on distant buildings
    const bannerTex = makeBannerTexture('ঢাকা ড্যাশ', 'রিকশা রাশ · ২০২৬');
    const bannerMat = new THREE.MeshStandardMaterial({
      map: bannerTex,
      emissiveMap: bannerTex,
      emissive: 0xffffff,
      emissiveIntensity: 0.55,
      roughness: 0.8,
      side: THREE.DoubleSide,
    });
    for (const side of [-1, 1]) {
      const banner = new THREE.Mesh(new THREE.PlaneGeometry(7, 1.75), bannerMat);
      banner.position.set(side * 12.5, 7.5, -34 - (side > 0 ? 14 : 0));
      banner.rotation.y = side > 0 ? -Math.PI / 2.2 : Math.PI / 2.2;
      this.scene.add(banner);
    }
  }

  buildTeaStall() {
    const group = new THREE.Group();
    group.position.set(8.4, 0, -14);
    const wood = std(0x5c3d2c, { roughness: 0.9 });
    const metal = std(0x8f8f96, { metalness: 0.65, roughness: 0.4 });
    mesh(group, new THREE.BoxGeometry(2.6, 1.05, 1.3), wood, [0, 0.55, 0], [0, 0, 0], true);
    mesh(group, new THREE.BoxGeometry(2.9, 0.12, 1.5), std(0x2f2228), [0, 1.12, 0]);
    // awning
    const awning = mesh(group, new THREE.BoxGeometry(3.1, 0.1, 2.2), std(0xc23b2f, { roughness: 0.85 }), [0, 2.55, 0.1], [0, 0, -0.12], false);
    // poles
    for (const x of [-1.45, 1.45]) {
      mesh(group, new THREE.CylinderGeometry(0.04, 0.04, 2.55, 6), metal, [x, 1.27, -0.85]);
    }
    // kettle
    mesh(group, new THREE.CylinderGeometry(0.16, 0.2, 0.3, 10), metal, [-0.55, 1.3, 0.1], [0, 0, 0], true);
    mesh(group, new THREE.CylinderGeometry(0.02, 0.02, 0.28, 5), metal, [-0.32, 1.34, 0.1], [0, 0, -0.9]);
    // cups
    for (let i = 0; i < 4; i++) {
      mesh(group, new THREE.CylinderGeometry(0.055, 0.04, 0.09, 8), std(0xf4e6c8), [0.2 + i * 0.17, 1.23, 0.15]);
    }
    // sign
    const signTex = makeShopTexture('চা ঘর', '#ffcf6e', '#3a1a12');
    const signMat = new THREE.MeshStandardMaterial({ map: signTex, emissiveMap: signTex, emissive: 0xffffff, emissiveIntensity: 1.1, roughness: 0.5 });
    this.neonMats.push(signMat);
    mesh(group, new THREE.PlaneGeometry(2.1, 0.52), signMat, [0, 2.24, -0.86]);
    // string lights
    for (let i = 0; i < 5; i++) {
      const bulb = new THREE.Mesh(new THREE.SphereGeometry(0.05, 6, 5), new THREE.MeshStandardMaterial({ color: 0xffd9a0, emissive: 0xffb050, emissiveIntensity: 2.2 }));
      bulb.position.set(-1.2 + i * 0.6, 2.42 - Math.sin((i / 4) * Math.PI) * 0.16, 0.9);
      group.add(bulb);
      const halo = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.glowTexture, color: 0xffb050, transparent: true, opacity: 0.45, depthWrite: false, blending: THREE.AdditiveBlending }));
      halo.position.copy(bulb.position);
      halo.scale.set(0.6, 0.6, 1);
      group.add(halo);
    }
    const light = new THREE.PointLight(0xffa85e, 3.2, 14, 2);
    light.position.set(0, 2.1, 0);
    group.add(light);
    // bench
    mesh(group, new THREE.BoxGeometry(1.5, 0.1, 0.45), wood, [-0.2, 0.55, 1.3]);
    for (const x of [-0.85, 0.45]) mesh(group, new THREE.BoxGeometry(0.1, 0.55, 0.4), wood, [x, 0.28, 1.3]);

    this.scene.add(group);
    this.props.push({ group, baseZ: -14, side: 1, kind: 'stall' });
  }

  /* ------------------------------------------------------------ obstacles */

  createBus() {
    const group = new THREE.Group();
    const label = pick(BUS_LABELS);
    const colors = [
      ['#1f7a4f', '#ffcf6e'],
      ['#b3263b', '#ffe0a3'],
      ['#265f9e', '#ffcf6e'],
      ['#7a2d7e', '#ffd166'],
    ];
    const [primary, secondary] = pick(colors);
    const tex = makeBusTexture(primary, secondary, label);
    const sideMat = new THREE.MeshStandardMaterial({ map: tex, roughness: 0.58, metalness: 0.08 });
    const plain = std(primary, { roughness: 0.6 });
    const glass = std(0x17222c, { roughness: 0.25, metalness: 0.35 });
    const body = new THREE.Mesh(new THREE.BoxGeometry(2.34, 2.5, 7.4), [sideMat, sideMat, plain, plain, glass, glass]);
    body.position.y = 1.72;
    body.castShadow = true;
    body.receiveShadow = true;
    group.add(body);

    // roof rack
    mesh(group, new THREE.BoxGeometry(1.9, 0.16, 4.6), std(0x3a3038, { metalness: 0.4, roughness: 0.6 }), [0, 3.06, 0.2], [0, 0, 0], true);
    mesh(group, new THREE.BoxGeometry(0.12, 0.12, 4.4), std(0x2a2228), [-0.85, 3.16, 0.2]);
    mesh(group, new THREE.BoxGeometry(0.12, 0.12, 4.4), std(0x2a2228), [0.85, 3.16, 0.2]);

    // back window + lights
    mesh(group, new THREE.PlaneGeometry(1.7, 0.9), std(0x131c26, { roughness: 0.2, metalness: 0.4 }), [0, 2.05, 3.716]);
    for (const x of [-0.85, 0.85]) {
      mesh(group, new THREE.SphereGeometry(0.12, 8, 6), new THREE.MeshStandardMaterial({ color: 0xff3a26, emissive: 0xff2a18, emissiveIntensity: 2.4 }), [x, 1.05, 3.72]);
    }
    // headlights
    for (const x of [-0.85, 0.85]) {
      mesh(group, new THREE.SphereGeometry(0.13, 8, 6), new THREE.MeshStandardMaterial({ color: 0xfff2c9, emissive: 0xffd27a, emissiveIntensity: 2.2 }), [x, 1.1, -3.72]);
    }
    // wheels
    const wheelGeo = new THREE.CylinderGeometry(0.48, 0.48, 0.3, 12);
    const wheelMat = std(0x141018, { roughness: 0.9 });
    for (const x of [-1.1, 1.1]) {
      for (const z of [-2.35, 2.3]) {
        mesh(group, wheelGeo, wheelMat, [x, 0.48, z], [0, 0, Math.PI / 2]);
      }
    }
    group.userData.type = 'bus';
    return { group, hx: 1.25, hz: 3.85, cy: 1.75, hy: 1.45, speedMul: rand(0.74, 0.9) };
  }

  createCNG() {
    const group = new THREE.Group();
    const green = std(0x1c8a5a, { roughness: 0.5, metalness: 0.15 });
    const yellow = std(0xe8b93c, { roughness: 0.55 });
    const glass = std(0x1a2630, { roughness: 0.25, metalness: 0.35 });
    mesh(group, new THREE.BoxGeometry(1.65, 1.0, 2.4), green, [0, 0.98, 0], [0, 0, 0], true);
    mesh(group, new THREE.BoxGeometry(1.55, 0.82, 1.3), green, [0, 1.72, 0.15], [0, 0, 0], true);
    mesh(group, new THREE.BoxGeometry(1.6, 0.16, 1.35), yellow, [0, 2.18, 0.15], [0, 0, 0], true);
    mesh(group, new THREE.PlaneGeometry(1.2, 0.5), glass, [0, 1.82, -0.51]);
    mesh(group, new THREE.PlaneGeometry(1.2, 0.46), glass, [0, 1.8, 0.81], [0, Math.PI, 0]);
    // front nose
    mesh(group, new THREE.BoxGeometry(1.2, 0.7, 0.7), green, [0, 0.78, -1.35], [0.18, 0, 0], true);
