function collectMango() {
  state.mangoes += 1;
  state.combo = Math.min(12, state.combo + 1);
  state.comboTimer = 2.2;
  const points = 25 * state.combo * (state.boosting ? 2 : 1);
  state.score += points;
  if (!state.boosting) state.boost = Math.min(1, state.boost + 0.145);
  audio.collect(state.combo);
  if (state.boost >= 0.999 && !state.boosting && !collectMango.announced) {
    collectMango.announced = true;
    toast('চা-বুস্ট প্রস্তুত — Shift চাপুন', 'good');
    setTimeout(() => { collectMango.announced = false; }, 5000);
  }
}

function handleNearMiss() {
  state.combo = Math.min(12, state.combo + 1);
  state.comboTimer = 2.2;
  state.score += 12;
  audio.nearMiss();
  if (Math.random() < 0.35) toast('নিয়ার মিস! +12', 'good');
}

function handleHit(obstacle) {
  if (state.mode !== 'playing') return;
  if (state.boosting) {
    state.score += 100;
    state.shake = Math.max(state.shake, 0.45);
    world.destroyObstacle(obstacle);
    world.burst(obstacle.x, 1.1, obstacle.z, 0xff7a3a, 26, 8);
    audio.nearMiss();
    toast('ধুম! +100', 'hot');
    return;
  }
  crash(obstacle);
}

function crash(obstacle) {
  if (state.mode !== 'playing') return;
  state.mode = 'crash';
  state.crashTimer = 0;
  state.boosting = false;
  state.ducking = false;
  state.duckHeld = false;
  state.duckUntil = 0;
  document.body.classList.remove('boosting');
  document.body.classList.add('crash');
  setTimeout(() => document.body.classList.remove('crash'), 700);
  state.shake = 1;
  audio.crash();
  const x = obstacle?.x ?? state.x;
  const z = obstacle?.z ?? 0;
  world.burst(x, 1.2, z, 0xff6a2e, 32, 9);
  world.burst(x, 0.6, z, 0xffcf6e, 18, 6);
  world.burst(state.x, 1, 0.8, 0x6b4a3a, 20, 5);
  setHud(false);
  if (navigator.vibrate) navigator.vibrate([60, 40, 120]);
}

function gameOver() {
  state.mode = 'over';
  state.overTimer = 0;
  setHud(false);
  const score = Math.floor(state.score);
  const isBest = score > state.best;
  if (isBest) {
    state.best = score;
    localStorage.setItem(BEST_KEY, String(state.best));
      await document.fonts.ready;
    }
  } catch { /* fonts are optional */ }
  boot();
}

init();

window.__dhakaDash = {
  get state() { return state; },
  get world() { return world; },
  get camera() { return camera; },
  startGame,
  goMenu,
  pauseGame,
  resumeGame,
  jump,
  moveLane,
  activateBoost,
  toast,
  spawn(type, lane, z) { return world.spawnObstacle(type, lane, z); },
  collectAt(lane, z = -1) { world.spawnMango(lane, z); },
};

update(dt, { speed, playerX, playerY, playerHeight, boosting = false, active = true }) {
  this.time += dt;
  this.speed = speed;
  const scroll = speed * dt;

  // road motion
  this.roadTexture.offset.y -= scroll / 24;
  this.sidewalkTexture.offset.y -= scroll / 16;

  // city scroll + recycle
  for (const b of this.city) {
    b.group.position.z += scroll;
    if (b.group.position.z > 52) {
      b.group.position.z -= CITY_SPAN;
      b.group.position.x = b.side * (9.6 + rand(3.5, 7.5));
    }
  }

  // props scroll + recycle
  for (const p of this.props) {
    p.group.position.z += scroll;
    if (p.group.position.z > 46) {
      p.group.position.z -= CITY_SPAN;
      p.group.position.x = p.side * (p.kind === 'tree' ? rand(9.1, 10.4) : p.kind === 'stall' ? 8.4 : 8.5);
      if (p.kind === 'cow') p.group.rotation.y = rand(0, Math.PI * 2);
    }
  }

  for (const w of this.wires) {
    w.group.position.z += scroll;
    if (w.group.position.z > 42) w.group.position.z -= 252;
  }

  // clouds drift
  for (const cloud of this.clouds) {
    cloud.position.x += dt * 1.4;
    if (cloud.position.x > 320) cloud.position.x = -320;
  }

  // neon flicker
  for (let i = 0; i < this.neonMats.length; i += 3) {
    const m = this.neonMats[i];
    m.emissiveIntensity = 1.05 + Math.sin(this.time * 3 + i) * 0.16 + (Math.random() < 0.008 ? -0.6 : 0);
  }

  // spawn
  if (active) {
    this.spawnTimer -= dt;
    if (this.spawnTimer <= 0) {
      this.spawnWave();
      const base = 17 / Math.max(speed, 8);
      this.spawnTimer = base * rand(0.92, 1.35);
    }
  }

  // obstacles
  for (let i = this.obstacles.length - 1; i >= 0; i--) {
    const o = this.obstacles[i];
    const own = (o.speedMul ?? 1) * speed;
    o.z += (speed - own) * dt;
    if (o.group.userData.type === 'cow') {
      o.x += (o.drift ?? 0) * dt;
      if (Math.abs(o.x - LANES[o.lane]) > 0.55) o.drift *= -1;
    }
    o.group.position.z = o.z;
    o.group.position.x = o.x;

    // collision
    if (active && !o.hit && !o.passed) {
      const dx = Math.abs(o.x - playerX);
      if (Math.abs(o.z) < o.hz + 1.25 && dx < o.hx + 0.68) {
        const pTop = playerY + playerHeight;
        const pBottom = playerY;
        if (pBottom < o.cy + o.hy && pTop > o.cy - o.hy) {
          o.hit = true;
          this.callbacks.onHit?.(o);
        }
      }
    }

    if (active && !o.passed && o.z > 3.2) {
      o.passed = true;
      if (!o.hit && Math.abs(o.x - playerX) < 2.35 && Math.abs(o.x - playerX) > 0.95) {
        this.callbacks.onNearMiss?.(o);
      }
    }

    if (o.z > DESPAWN_Z) {
      this.releaseObstacle(o);
      this.obstacles.splice(i, 1);
    }
  }

  // mangoes
  for (let i = this.mangoes.length - 1; i >= 0; i--) {
    const m = this.mangoes[i];
    m.z += scroll;
    const bob = Math.sin(this.time * 3.4 + m.phase) * 0.12;
    m.group.position.set(m.x, 1.15 + bob, m.z);
    m.group.rotation.y += dt * 2.2;
    m.ring.rotation.z += dt * 3.4;
    if (active && !m.collected && Math.abs(m.z) < 1.7 && Math.abs(m.x - playerX) < 1.35 && playerY < 2.6) {
      m.collected = true;
      this.callbacks.onCollect?.(m);

    localStorage.setItem(BEST_KEY, String(state.best));
  }
  els.finalScore.textContent = score.toLocaleString('en-US');
  els.finalDistance.textContent = Math.floor(state.distance).toLocaleString('en-US');
  els.finalMangoes.textContent = state.mangoes;
  els.finalBest.textContent = state.best;
  els.newBest.classList.toggle('is-hidden', !isBest);
  els.overKicker.textContent = 'খেলা শেষ';
  els.overTitle.textContent = isBest ? 'দুর্দান্ত ছুট!' : 'দুর্ঘটনা';
  updateBestUI();
  showScreen('over');
  audio.gameOver();
  audio.setEngine(0, false, false);
}

function startGame() {
  state.mode = 'playing';
  state.score = 0;
  state.scoreAcc = 0;
  state.distance = 0;
  state.mangoes = 0;
  state.combo = 0;
  state.comboTimer = 0;
  state.boost = 0;
  state.boostTime = 0;
  state.boosting = false;
  state.speed = 16;
  state.lane = 1;
  state.x = 0;
  state.y = 0;
  state.vy = 0;
  state.grounded = true;
  state.ducking = false;
  state.duckHeld = false;
  state.duckUntil = 0;
  state.lean = 0;
  state.shake = 0;
  state.crashTimer = 0;
  state.overTimer = 0;
  collectMango.announced = false;
  lastHud = { score: -1, distance: -1, best: -1, boost: -1, combo: -1 };
  if (document.activeElement && document.activeElement.blur) document.activeElement.blur();
  document.body.classList.remove('boosting', 'crash');
  rickshaw.root.position.set(0, 0, 0);
