        else if (s.grounded) { s.vy = 8.6; s.grounded = false; }
      } else if (dcur < 32 && (tcur === 'bus' || tcur === 'car' || tcur === 'cng' || tcur === 'cow')) {
        if (nearest[best] > 30) s.lane = best;
      }

      // physics
      if (!s.grounded) {
        s.vy -= 23*dt; s.y += s.vy*dt;
        if (s.y <= 0) { s.y = 0; s.vy = 0; s.grounded = true; }
      }
      s.ducking = duckWanted && s.grounded;
      s.x += (LANES[s.lane] - s.x) * Math.min(1, dt*11);
      s.distance = dist; s.speed = speed;

      D.world.update(dt, { speed, playerX: s.x, playerY: s.y, playerHeight: s.ducking?1.42:2.0, boosting: false, active: true });
      if (s.mode !== 'playing') {
        crashInfo = { dist:+dist.toFixed(1), lane:s.lane, x:+s.x.toFixed(2), y:+s.y.toFixed(2), duck:s.ducking,
