function bindInput() {
  window.addEventListener('keydown', (e) => {
    const key = e.key;
    if (['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', ' ', 'Spacebar'].includes(key)) e.preventDefault();
    if (e.repeat) return;

    if (key === 'm' || key === 'M') { toggleMute(); return; }

    if (state.mode === 'menu') {
